$srcEntries = Parse-Tree $src[1]
$srcEntries | Where-Object Name -eq 'core' | Format-List
$test = Read-GitObject 'dad0de38a070e712b0ba0508ec4804e2314925fc'
Parse-Tree $test[1] | Where-Object { $_.Name -match 'handoff|smartSelect' } | Format-Table -AutoSize | Out-String -Width 120"}

